const bank = "MERCADO PAGO";
const linhas = $input.item.json.lines;
const transactions = [];

let current = null;
const reDate = /^\d{2}-\d{2}-\d{4}$/;
const reEnd = /^\d+\s+R\$\s*-?[\d.]+,\d{2}\s+R\$\s*-?[\d.]+,\d{2}$/;

// Pegar Nome do Cliente
let clientName = linhas[2];

for (const line of linhas) {

  // ignora cabeçalhos
  if (
    line === "DETALHE DOS MOVIMENTOS" ||
    line.startsWith("Data Descrição") ||
    /^Saldo final:/.test(line) ||
    /^Saldo inicial:/.test(line) ||
    /^Entradas:/.test(line) ||
    /^Saidas:/.test(line) ||
    /^Data de geração:/.test(line) ||
    /^Você tem alguma dúvida/.test(line) ||
    /^Mercado Pago Instituição/.test(line) ||
    /^Encontre nossos canais/.test(line) ||
    /^\d+\/\d+$/.test(line)
  ) {
    continue;
  }

  // início de uma movimentação
  if (reDate.test(line)) {

    if (current) {
      transactions.push(current);
    }

    current = {
      lines: [line]
    };

    continue;
  }

  if (!current) continue;

  current.lines.push(line);

  // terminou a movimentação
  if (reEnd.test(line)) {
    transactions.push(current);
    current = null;
  }

}

if (current) {
  transactions.push(current);
}

// Transforma os blocos em transações estruturadas
const result = transactions.map(item => {

  const lines = [...item.lines];

  const data = lines.shift().replace(/-/g, "/");

  // Última linha: ID + Valor + Saldo
  const lastLine = lines.pop();

  const match = lastLine.match(/^(\d+)\s+R\$\s*(-?[\d.]+,\d{2})\s+R\$\s*-?[\d.]+,\d{2}$/);

  let documento = "";
  let valor = "";
  let tipoTransacao = "";

  if (match) {

    documento = match[1];

    tipoTransacao = match[2].startsWith("-")
      ? "SAIDA"
      : "ENTRADA";

    valor = match[2]
      .replace("-", "")
      .replace(/\./g, "");

  }

  return {
    data,
    documento,
    descricao: lines.join(" ").replace(/\s+/g, " ").trim(),
    valor,
    tipoTransacao
  };

});

return {
  bank,
  clientName,
  count: result.length,
  transacoes: result
};
